export const meta = {
  "slug": "tabler-rotate-360",
  "family": "tabler",
  "name": "rotate-360",
  "category": "Navigation",
  "motion": "spin",
  "component": "createTablerRotate360Icon"
};

export function createTablerRotate360Icon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
